export function billingFlag(enabled: boolean) {
  if (!enabled) {
    return { enabled: false, reason: "Off" };
  }
  return { enabled: true };
}

export function supportFlag(enabled: boolean) {
  if (!enabled) {
    return { enabled: false, reason: "Off" };
  }
  return { enabled: true };
}
